export namespace GraphCorpusApi {
  // ==================== Node (图可视化需要) ====================
  export interface NodeItem {
    id: string; // 后端序列化为字符串，避免 JS 大整数精度丢失
    tenant_code: string;
    label: string;
    name: string;
    description?: string;
    corpus?: CorpusValue; // 语料列表
    ai_instruction?: Record<string, unknown>;
    properties?: Record<string, unknown>;
    is_active: number;
    is_deleted: number;
    created_by?: string;
    updated_by?: string;
    created_at?: string;
    updated_at?: string;
  }

  // ==================== Edge (图可视化需要) ====================
  export interface EdgeItem {
    id: string; // 后端序列化为字符串，避免 JS 大整数精度丢失
    tenant_code: string;
    source_node_id: string;
    target_node_id: string;
    relation_type: string;
    explanation?: string;
    meta_data?: Record<string, unknown>;
    is_active: number;
    is_deleted: number;
    created_by?: string;
    updated_by?: string;
    created_at?: string;
    updated_at?: string;
    // 冗余字段
    source_name?: string;
    target_name?: string;
    source_label?: string;
    target_label?: string;
  }

  // ==================== Stats ====================
  export interface GraphStats {
    total_nodes: number;
    total_edges: number;
    nodes_by_label: Record<string, number>;
    edges_by_relation: Record<string, number>;
  }

  // ==================== Visualization ====================
  export interface VisualizationParams {
    tenant_code?: string;
    min_degree?: number;
    limit?: number;
  }

  export interface VisualizationStats {
    total_nodes: number;
    total_edges: number;
    filtered_nodes: number;
    filtered_edges: number;
    min_degree: number;
  }

  export interface VisualizationResponse {
    nodes: NodeItem[];
    edges: EdgeItem[];
    stats: VisualizationStats;
  }

